insert into public.carrier_services("id","carrier_id","transport_mode","service_type","origin_country","origin_region","destination_country","destination_region","provider_service_code","max_capacity_kg","max_volume_m3","supports_refrigerated","temperature_min_c","temperature_max_c","supports_hazardous","supports_fragile","supports_oversized","supports_cross_border","customs_coordination_included","active","response_channels","required_certifications") select "id","carrier_id","transport_mode","service_type","origin_country","origin_region","destination_country","destination_region","provider_service_code","max_capacity_kg","max_volume_m3","supports_refrigerated","temperature_min_c","temperature_max_c","supports_hazardous","supports_fragile","supports_oversized","supports_cross_border","customs_coordination_included","active","response_channels","required_certifications" from jsonb_populate_record(null::public.carrier_services,'{"id":"e5000005-0000-4000-8000-000000000051","carrier_id":"e5000001-0000-4000-8000-000000000005","transport_mode":"ROAD","service_type":"FTL","origin_country":"GT","origin_region":"Guatemala City","destination_country":"SV","destination_region":"San Salvador","provider_service_code":"HAC50_C05_GENERAL","max_capacity_kg":18000,"max_volume_m3":60,"supports_refrigerated":false,"temperature_min_c":null,"temperature_max_c":null,"supports_hazardous":false,"supports_fragile":false,"supports_oversized":false,"supports_cross_border":true,"customs_coordination_included":false,"active":true,"response_channels":["MANUAL"],"required_certifications":[]}'::jsonb) on conflict do nothing;
insert into public.service_areas("id","carrier_service_id","area_role","coverage","granularity","country_code","region_code","city","postal_code","geometry","fulfilment_source","fulfilment_partner_id","evidence_reference","verified_at","valid_from","valid_until","active") select "id","carrier_service_id","area_role","coverage","granularity","country_code","region_code","city","postal_code","geometry","fulfilment_source","fulfilment_partner_id","evidence_reference","verified_at","valid_from","valid_until","active" from jsonb_populate_record(null::public.service_areas,'{"id":"e5000007-0000-4000-8000-000000005101","carrier_service_id":"e5000005-0000-4000-8000-000000000051","area_role":"PICKUP","coverage":"INCLUDE","granularity":"CITY","country_code":"GT","region_code":null,"city":"Guatemala City","postal_code":null,"geometry":null,"fulfilment_source":"OWN","fulfilment_partner_id":null,"evidence_reference":"SIMULATED:v2-carrier-fleet-80:area","verified_at":"2026-10-15T00:00:00Z","valid_from":"2026-10-16T00:00:00Z","valid_until":"2026-10-30T00:00:00Z","active":true}'::jsonb) on conflict do nothing;
insert into public.service_areas("id","carrier_service_id","area_role","coverage","granularity","country_code","region_code","city","postal_code","geometry","fulfilment_source","fulfilment_partner_id","evidence_reference","verified_at","valid_from","valid_until","active") select "id","carrier_service_id","area_role","coverage","granularity","country_code","region_code","city","postal_code","geometry","fulfilment_source","fulfilment_partner_id","evidence_reference","verified_at","valid_from","valid_until","active" from jsonb_populate_record(null::public.service_areas,'{"id":"e5000007-0000-4000-8000-000000005104","carrier_service_id":"e5000005-0000-4000-8000-000000000051","area_role":"DELIVERY","coverage":"INCLUDE","granularity":"CITY","country_code":"SV","region_code":null,"city":"San Salvador","postal_code":null,"geometry":null,"fulfilment_source":"OWN","fulfilment_partner_id":null,"evidence_reference":"SIMULATED:v2-carrier-fleet-80:area","verified_at":"2026-10-15T00:00:00Z","valid_from":"2026-10-16T00:00:00Z","valid_until":"2026-10-30T00:00:00Z","active":true}'::jsonb) on conflict do nothing;
insert into public.service_lanes("id","carrier_service_id","pickup_area_id","delivery_area_id","lane_kind","transport_mode","evidence_reference","verified_at","valid_from","valid_until","active","cross_border_review_required","cross_border_prohibited","planned_transit_minutes","transit_provenance_status") select "id","carrier_service_id","pickup_area_id","delivery_area_id","lane_kind","transport_mode","evidence_reference","verified_at","valid_from","valid_until","active","cross_border_review_required","cross_border_prohibited","planned_transit_minutes","transit_provenance_status" from jsonb_populate_record(null::public.service_lanes,'{"id":"e5000008-0000-4000-8000-000000000511","carrier_service_id":"e5000005-0000-4000-8000-000000000051","pickup_area_id":"e5000007-0000-4000-8000-000000005101","delivery_area_id":"e5000007-0000-4000-8000-000000005104","lane_kind":"DIRECT","transport_mode":"ROAD","evidence_reference":"SIMULATED:v2-carrier-fleet-80:lane","verified_at":"2026-10-15T00:00:00Z","valid_from":"2026-10-16T00:00:00Z","valid_until":"2026-10-30T00:00:00Z","active":true,"cross_border_review_required":true,"cross_border_prohibited":false,"planned_transit_minutes":null,"transit_provenance_status":"UNKNOWN"}'::jsonb) on conflict do nothing;
update public.carrier_operators set verified_at=now()-interval '1 day' where id in ('e5000003-0000-4000-8000-000000000001','e5000003-0000-4000-8000-000000000005');
update public.service_areas set verified_at=now()-interval '1 day',valid_from=now()-interval '7 days',valid_until=now()+interval '30 days' where id in (select pickup_area_id from public.service_lanes where id='e5000008-0000-4000-8000-000000000511' union select delivery_area_id from public.service_lanes where id='e5000008-0000-4000-8000-000000000511');
update public.service_lanes set verified_at=now()-interval '1 day',valid_from=now()-interval '7 days',valid_until=now()+interval '30 days' where id='e5000008-0000-4000-8000-000000000511';
create temp table border_refs(name text primary key,v jsonb);grant all on border_refs to authenticated;
insert into border_refs values('context',(select jsonb_build_object('schemaVersion','2.0','serviceId',l.carrier_service_id,'laneId',l.id,
 'executionId',null,'operationReference','SIMULATED:border:test:1','routeFingerprint',repeat('a',64),
 'fromCountry','GT','toCountry','SV','checkpointReference','SIMULATED:checkpoint-not-verified',
 'window',jsonb_build_object('startsAt',now()-interval '1 hour','endsAt',now()+interval '1 day'),
 'requiredDocuments',jsonb_build_array('MANIFEST','CARRIER_PERMIT'),'provenance','SIMULATED')
 from public.service_lanes l where carrier_service_id='e5000005-0000-4000-8000-000000000051' order by id limit 1));
insert into border_refs values('documents',(select jsonb_agg(jsonb_build_object('code',code,'reference','SIMULATED:'||code,
 'checkedAt',now()-interval '2 hours','validUntil',now()+interval '2 days')) from unnest(array['MANIFEST','CARRIER_PERMIT']) code));
create function pg_temp.border_call(a text,v jsonb default null,ver integer default null,i uuid default null,k uuid default null) returns jsonb
language sql as $$select public.border_operations_v2('e5000003-0000-4000-8000-000000000005','e5000001-0000-4000-8000-000000000005',a,i,ver,k,v);$$;
create function pg_temp.review(s text) returns jsonb language sql as $$select jsonb_build_object('status',s,'documents',(select v from border_refs where name='documents'),'note','SIMULATED internal review');$$;
create function pg_temp.passage(s text) returns jsonb language sql as $$select jsonb_build_object('status',s,'occurredAt',now(),'reference','SIMULATED:'||s);$$;
create function pg_temp.crossing_id() returns uuid language sql as $$select (v#>>'{data,id}')::uuid from border_refs where name='created';$$;

select ok(private.valid_border_value((select v from border_refs where name='context'),'context'),'valid explicit context');
select ok(not private.valid_border_value((select v||'{"toCountry":"GT"}' from border_refs where name='context'),'context'),'same-country pair rejected');
select ok(not private.valid_border_value((select v||'{"requiredDocuments":[]}' from border_refs where name='context'),'context'),'empty checklist rejected');
select ok(not private.valid_border_value((select v||'{"requiredDocuments":["X","X"]}' from border_refs where name='context'),'context'),'duplicate checklist rejected');
select ok(not private.valid_border_value(pg_temp.review('APPROVED')||'{"governmentVerified":true}','review'),'invented verified claim rejected');
set local role authenticated;set local request.jwt.claims='{"sub":"e5000002-0000-4000-8000-000000000005","role":"authenticated"}';
insert into border_refs values('created',pg_temp.border_call('create',(select v from border_refs where name='context'),0,null,'b5500000-0000-4000-8000-000000000001'));
select is((select v#>>'{data,version}' from border_refs where name='created'),'1','creation persists version 1');
select is((select v#>>'{data,reviewStatus}' from border_refs where name='created'),'PENDING','creation never auto approves');
select is((select v#>>'{data,passageStatus}' from border_refs where name='created'),'NOT_STARTED','creation does not move a truck');
select is(pg_temp.border_call('create',(select v from border_refs where name='context'),0,null,'b5500000-0000-4000-8000-000000000001')->>'replay','true','identical retry replays');
select throws_ok($$select pg_temp.border_call('create',(select v||'{"operationReference":"changed"}' from border_refs where name='context'),0,null,'b5500000-0000-4000-8000-000000000001')$$,'PT409','IDEMPOTENCY_CONFLICT','changed payload conflicts');
select throws_ok($$select pg_temp.border_call('create',(select v from border_refs where name='context'),0,null,gen_random_uuid())$$,'PT409','BORDER_OPERATION_CONFLICT','duplicate operation with another key conflicts');
select throws_ok($$select pg_temp.border_call('create',(select v||'{"fromCountry":"SV","toCountry":"GT"}' from border_refs where name='context'),0,null,gen_random_uuid())$$,'PT409','BORDER_CATALOG_UNAVAILABLE','reverse lane never inferred');
select throws_ok($$select pg_temp.border_call('create',(select v||'{"serviceId":"e5000005-0000-4000-8000-000000000011"}' from border_refs where name='context'),0,null,gen_random_uuid())$$,'PT409','BORDER_CATALOG_UNAVAILABLE','foreign service rejected');
select throws_ok($$select pg_temp.border_call('review',pg_temp.review('APPROVED'),1,pg_temp.crossing_id(),gen_random_uuid())$$,'PT409','BORDER_INVALID_TRANSITION','cannot skip review');
select throws_ok($$select pg_temp.border_call('passage',pg_temp.passage('CROSSED'),1,pg_temp.crossing_id(),gen_random_uuid())$$,'PT409','BORDER_INVALID_TRANSITION','cannot jump to crossed');
select lives_ok($$select pg_temp.border_call('review',pg_temp.review('IN_REVIEW')||'{"documents":[]}',1,pg_temp.crossing_id(),'b5500000-0000-4000-8000-000000000002')$$,'in review accepts missing documents');
select throws_ok($$select pg_temp.border_call('review',pg_temp.review('IN_REVIEW'),1,pg_temp.crossing_id(),gen_random_uuid())$$,'PT409','STALE_DRAFT','stale writer rejected');
select throws_ok($$select pg_temp.border_call('review',pg_temp.review('APPROVED')||'{"documents":[]}',2,pg_temp.crossing_id(),gen_random_uuid())$$,'PT409','BORDER_DOCUMENTS_INCOMPLETE','approval needs all documents');
select throws_ok($$select pg_temp.border_call('review',jsonb_set(pg_temp.review('APPROVED'),'{documents,0,validUntil}',to_jsonb(now()+interval '1 hour')),2,pg_temp.crossing_id(),gen_random_uuid())$$,'PT409','BORDER_DOCUMENTS_INCOMPLETE','partial validity cannot approve whole activity');
select throws_ok($$select pg_temp.border_call('review',jsonb_set(pg_temp.review('APPROVED'),'{documents,0,checkedAt}',to_jsonb(now()+interval '1 hour')),2,pg_temp.crossing_id(),gen_random_uuid())$$,'PT400','VALIDATION_ERROR','future evidence rejected');
select lives_ok($$select pg_temp.border_call('review',pg_temp.review('NEEDS_DOCUMENTS')||'{"documents":[]}',2,pg_temp.crossing_id(),gen_random_uuid())$$,'missing documents has explicit state');
select throws_ok($$select pg_temp.border_call('review',pg_temp.review('APPROVED'),3,pg_temp.crossing_id(),gen_random_uuid())$$,'PT409','BORDER_INVALID_TRANSITION','resubmission requires new review');
select lives_ok($$select pg_temp.border_call('review',pg_temp.review('IN_REVIEW'),3,pg_temp.crossing_id(),gen_random_uuid())$$,'documents can be resubmitted');
select lives_ok($$select pg_temp.border_call('review',pg_temp.review('APPROVED'),4,pg_temp.crossing_id(),gen_random_uuid())$$,'complete current documents approved internally');
select is(pg_temp.border_call('read',null,null,pg_temp.crossing_id())#>>'{data,passageStatus}','NOT_STARTED','approval does not start passage');
select is(pg_temp.border_call('assessment',null,null,pg_temp.crossing_id())#>>'{catalogCheck,status}','eligible','current catalog snapshot accepted');
select lives_ok($$select pg_temp.border_call('passage',pg_temp.passage('APPROACHING'),5,pg_temp.crossing_id(),gen_random_uuid())$$,'explicit approach event');
select throws_ok($$select pg_temp.border_call('passage',jsonb_set(pg_temp.passage('WAITING'),'{occurredAt}',to_jsonb(now()+interval '1 minute')),6,pg_temp.crossing_id(),gen_random_uuid())$$,'PT400','BORDER_EVENT_TIME_INVALID','future movement rejected');
select throws_ok($$select pg_temp.border_call('passage',jsonb_set(pg_temp.passage('WAITING'),'{occurredAt}',to_jsonb(now()-interval '1 minute')),6,pg_temp.crossing_id(),gen_random_uuid())$$,'PT400','BORDER_EVENT_TIME_INVALID','out of order movement rejected');
select lives_ok($$select pg_temp.border_call('passage',pg_temp.passage('WAITING'),6,pg_temp.crossing_id(),gen_random_uuid())$$,'explicit waiting event');
select lives_ok($$select pg_temp.border_call('passage',pg_temp.passage('HELD'),7,pg_temp.crossing_id(),gen_random_uuid())$$,'hold preserves separate review');
select is(pg_temp.border_call('read',null,null,pg_temp.crossing_id())#>>'{data,reviewStatus}','APPROVED','physical hold does not rewrite document decision');
select throws_ok($$select pg_temp.border_call('passage',pg_temp.passage('RELEASED'),8,pg_temp.crossing_id(),gen_random_uuid())$$,'PT409','BORDER_INVALID_TRANSITION','hold must return to inspection');
select lives_ok($$select pg_temp.border_call('passage',pg_temp.passage('INSPECTION'),8,pg_temp.crossing_id(),gen_random_uuid())$$,'inspection follows hold');
select lives_ok($$select pg_temp.border_call('passage',pg_temp.passage('RELEASED'),9,pg_temp.crossing_id(),gen_random_uuid())$$,'simulated release requires explicit report');
select throws_ok($$select pg_temp.border_call('review',pg_temp.review('IN_REVIEW'),10,pg_temp.crossing_id(),gen_random_uuid())$$,'PT409','BORDER_REVIEW_LOCKED','released review is immutable');
select lives_ok($$select pg_temp.border_call('passage',pg_temp.passage('CROSSED'),10,pg_temp.crossing_id(),gen_random_uuid())$$,'explicit final crossing');
select throws_ok($$select pg_temp.border_call('review',pg_temp.review('IN_REVIEW'),11,pg_temp.crossing_id(),gen_random_uuid())$$,'PT409','BORDER_TERMINAL_CROSSING','completed crossing cannot restart');
select is(jsonb_array_length(pg_temp.border_call('history',null,null,pg_temp.crossing_id())->'data'),11,'every successful version has one event');
select is(pg_temp.border_call('history',null,null,pg_temp.crossing_id())#>>'{data,0,version}','11','history returns newest first');
select is(pg_temp.border_call('read',null,null,pg_temp.crossing_id())#>>'{data,context,provenance}','SIMULATED','simulation identity is retained after crossing');
select throws_ok($$update public.carrier_border_crossings set review_status='APPROVED'$$,'42501',null,'direct writes denied');
select throws_ok($$select * from private.border_command_events$$,'42501',null,'raw history table denied');
select throws_ok($$select public.border_operations_v2('e5000003-0000-4000-8000-000000000001','e5000001-0000-4000-8000-000000000005','list',null,null,null,null)$$,'PT403','FORBIDDEN_CARRIER_IDENTITY','operator spoof rejected');

-- The same documentation context may be planned, but cannot produce physical reports without an active execution.
insert into border_refs values('reported',pg_temp.border_call('create',(select v||'{"operationReference":"reported-plan","provenance":"CARRIER_REPORTED"}' from border_refs where name='context'),0,null,gen_random_uuid()));
select throws_ok($$select pg_temp.border_call('passage',pg_temp.passage('APPROACHING'),1,(select (v#>>'{data,id}')::uuid from border_refs where name='reported'),gen_random_uuid())$$,'PT409','BORDER_EXECUTION_NOT_ACTIVE','reported movement requires native active execution');

reset role;
update public.carrier_operators set role='OPERATOR' where id='e5000003-0000-4000-8000-000000000005';
set local role authenticated;
select is(pg_temp.border_call('read',null,null,pg_temp.crossing_id())#>>'{data,version}','11','operator may read own crossing');
select throws_ok($$select pg_temp.border_call('create',(select v||'{"operationReference":"operator-write"}' from border_refs where name='context'),0,null,gen_random_uuid())$$,'PT403','FORBIDDEN_CARRIER_ROLE','operator cannot create review');
reset role;
update public.carrier_operators set role='DISPATCHER' where id='e5000003-0000-4000-8000-000000000005';
set local role authenticated;
select lives_ok($$select pg_temp.border_call('review',pg_temp.review('IN_REVIEW')||'{"documents":[]}',1,(select (v#>>'{data,id}')::uuid from border_refs where name='reported'),gen_random_uuid())$$,'dispatcher may perform internal review');

reset role;
select is((select count(*)::integer from private.border_command_events),13,'failed commands append no events');
select is((select count(*)::integer from private.border_command_receipts),13,'failed commands append no receipts');
update public.service_lanes set version=version+1 where id=(select (v->>'laneId')::uuid from border_refs where name='context');
set local role authenticated;
select is(pg_temp.border_call('assessment',null,null,pg_temp.crossing_id())#>>'{catalogCheck,status}','unknown','lane revision invalidates snapshot');
select ok(pg_temp.border_call('assessment',null,null,pg_temp.crossing_id())#>'{catalogCheck,reasons}' ? 'BORDER_CATALOG_CHANGED','catalog change has stable reason');
reset role;
update public.service_lanes set version=version-1 where id=(select (v->>'laneId')::uuid from border_refs where name='context');
update public.service_areas set version=version+1 where id=(select pickup_area_id from public.service_lanes where id=(select (v->>'laneId')::uuid from border_refs where name='context'));
set local role authenticated;
select ok(pg_temp.border_call('assessment',null,null,pg_temp.crossing_id())#>'{catalogCheck,reasons}' ? 'BORDER_CATALOG_CHANGED','area revision also invalidates snapshot');
reset role;
update public.service_lanes set cross_border_prohibited=true,cross_border_prohibition_reference='SIMULATED prohibition' where id=(select (v->>'laneId')::uuid from border_refs where name='context');
set local role authenticated;
select is(pg_temp.border_call('assessment',null,null,pg_temp.crossing_id())#>>'{catalogCheck,status}','ineligible','current prohibition overrides old review');
set local request.jwt.claims='{"sub":"e5000002-0000-4000-8000-000000000001","role":"authenticated"}';
select is((select count(*)::integer from public.carrier_border_crossings),0,'RLS hides foreign crossings');
select throws_ok($$select public.border_operations_v2('e5000003-0000-4000-8000-000000000001','e5000001-0000-4000-8000-000000000001','read',pg_temp.crossing_id(),null,null,null)$$,'PT404','BORDER_CROSSING_NOT_FOUND','foreign crossing lookup gives no record');
set local role anon;
select throws_ok($$select public.border_operations_v2(null,null,'list',null,null,null,null)$$,'42501',null,'anonymous RPC denied');
select throws_ok($$select * from public.carrier_border_crossings$$,'42501',null,'anonymous table denied');
reset role;
select ok((select relrowsecurity from pg_class where oid='public.carrier_border_crossings'::regclass),'public table uses RLS');
select ok((select relrowsecurity from pg_class where oid='private.border_command_receipts'::regclass),'receipts use RLS');
select ok((select relrowsecurity from pg_class where oid='private.border_command_events'::regclass),'audit events use RLS');
select * from finish();
rollback;
